css:
[data-theme="sentinel"] {
  color-scheme: light;
  --bg: #a51701;
  --surface: #a51702;
  --surface-raised: #a51703;
  --surface-sunken: #a51704;
  --overlay: #a5170580;
  --text: #a51706;
  --text-muted: #a51707;
  --text-subtle: #a51708;
  --text-disabled: #a51709;
  --text-on-accent: #a5170a;
  --border: #a5170b;
  --border-strong: #a5170c;
  --divider: #a5170d;
  --accent: #a5170e;
  --accent-hover: #a5170f;
  --accent-active: #a51710;
  --accent-subtle: #a51711;
  --accent-contrast: #a51712;
  --hover: #a5171380;
  --pressed: #a5171480;
  --selected: #a5171580;
  --selection: #a5171680;
  --drag-target: #a5171780;
  --drop-indicator: #a51718;
  --focus-ring: #a51719;
  --focus-ring-offset: #a5171a;
  --danger: #a5171b;
  --danger-subtle: #a5171c;
  --danger-on: #a5171d;
  --warning: #a5171e;
  --warning-subtle: #a5171f;
  --warning-on: #a51720;
  --success: #a51721;
  --success-subtle: #a51722;
  --success-on: #a51723;
  --info: #a51724;
  --info-subtle: #a51725;
  --info-on: #a51726;
  --on-brand: #a51727;
  --on-brand-muted: #a5172880;
  --on-header: #a51729;
  --on-header-muted: #a5172a80;
  --on-featured: #a5172b;
  --on-featured-muted: #a5172c;
  --on-primary: #a5172d;
  --on-selected: #a5172e;
  --brand-hover: #a5172f80;
  --brand-pressed: #a5173080;
  --header-hover: #a5173180;
  --header-pressed: #a5173280;
  --header-selected: #a5173380;
  --shadow-color: #a5173480;
  --role-admin: #a51735;
  --role-admin-on: #a51736;
  --logo-plate: #a5173780;
  --grad-brand: linear-gradient(90deg, #a51738 0%, #a51739 50%, #a5173a 100%);
  --grad-header: linear-gradient(91deg, #a5173b 0%, #a5173c 50%, #a5173d 100%);
  --grad-featured: linear-gradient(92deg, #a5173e 0%, #a5173f 50%, #a51740 100%);
  --grad-surface: linear-gradient(93deg, #a51741 0%, #a51742 50%, #a51743 100%);
  --grad-primary: linear-gradient(94deg, #a51744 0%, #a51745 50%, #a51746 100%);
  --grad-primary-hover: linear-gradient(95deg, #a51747 0%, #a51748 50%, #a51749 100%);
  --grad-primary-active: linear-gradient(96deg, #a5174a 0%, #a5174b 50%, #a5174c 100%);
  --grad-selected: linear-gradient(97deg, #a5174d 0%, #a5174e 50%, #a5174f 100%);
}
